#![allow(dead_code,unused_imports)]pub mod game{pub mod types{use std::collections::BTreeSet;pub type Cell=(i32,i32);pub const ITEM_COUNT:usize=6;pub const PLUM:usize=0;pub const LEMON:usize=1;pub const APPLE:usize=2;pub const BANANA:usize=3;pub const IRON:usize=4;pub const WOOD:usize=5;pub type Stock=[i32;ITEM_COUNT];#[derive(Clone,Copy,Debug,Eq,PartialEq,Ord,PartialOrd,Hash)]pub enum PlantKind{Plum,Lemon,Apple,Banana,}impl PlantKind{pub const ALL:[PlantKind;4]=[PlantKind::Plum,PlantKind::Lemon,PlantKind::Apple,PlantKind::Banana,];pub fn parse(value:&str)->Option<PlantKind>{match value.to_ascii_uppercase().as_str(){"PLUM"=>Some(PlantKind::Plum),"LEMON"=>Some(PlantKind::Lemon),"APPLE"=>Some(PlantKind::Apple),"BANANA"=>Some(PlantKind::Banana),_=>None,}}pub fn as_str(self)->&'static str{match self{PlantKind::Plum=>"PLUM",PlantKind::Lemon=>"LEMON",PlantKind::Apple=>"APPLE",PlantKind::Banana=>"BANANA",}}pub fn item_index(self)->usize{match self{PlantKind::Plum=>PLUM,PlantKind::Lemon=>LEMON,PlantKind::Apple=>APPLE,PlantKind::Banana=>BANANA,}}}#[derive(Clone,Copy,Debug,Eq,PartialEq)]pub struct Stats{pub movement_speed:i32,pub carry_capacity:i32,pub harvest_power:i32,pub chop_power:i32,}impl Stats{pub const STARTER_GOLD:Stats=Stats{movement_speed:1,carry_capacity:1,harvest_power:1,chop_power:1,};pub const STARTER_WOOD:Stats=Stats{movement_speed:1,carry_capacity:1,harvest_power:1,chop_power:0,};pub fn tuple(self)->(i32,i32,i32,i32){(self.movement_speed,self.carry_capacity,self.harvest_power,self.chop_power,)}}#[derive(Clone,Debug,Eq,PartialEq)]pub struct Unit{pub id:i32,pub player:usize,pub cell:Cell,pub stats:Stats,pub carry:Stock,}impl Unit{pub fn total_carried(&self)->i32{self.carry.iter().sum()}pub fn free_capacity(&self)->i32{self.stats.carry_capacity-self.total_carried()}}#[derive(Clone,Debug,Eq,PartialEq)]pub struct Plant{pub kind:PlantKind,pub cell:Cell,pub size:i32,pub health:i32,pub fruits:i32,pub cooldown:i32,}#[derive(Clone,Debug,Eq,PartialEq)]pub struct GameState{pub width:i32,pub height:i32,pub walkable:BTreeSet<Cell>,pub shacks:[Cell;2],pub inventories:[Stock;2],pub units:Vec<Unit>,pub plants:Vec<Plant>,pub scores:[i32;2],pub turn:i32,pub next_id:i32,pub iron:BTreeSet<Cell>,pub water:BTreeSet<Cell>,}impl GameState{pub fn empty(width:i32,height:i32)->GameState{GameState{width,height,walkable:BTreeSet::new(),shacks:[(0,0),(0,0)],inventories:[[0;ITEM_COUNT];2],units:Vec::new(),plants:Vec::new(),scores:[0,0],turn:1,next_id:0,iron:BTreeSet::new(),water:BTreeSet::new(),}}pub fn plant_at(&self,cell:Cell)->Option<usize>{self.plants.iter().position(|plant|plant.cell==cell)}pub fn unit(&self,id:i32)->Option<&Unit>{self.units.iter().find(|unit|unit.id==id)}pub fn unit_mut(&mut self,id:i32)->Option<&mut Unit>{self.units.iter_mut().find(|unit|unit.id==id)}pub fn units_for(&self,player:usize)->Vec<&Unit>{let mut units:Vec<&Unit> =self.units.iter().filter(|unit|unit.player==player).collect();units.sort_by_key(|unit|unit.id);units}}}pub mod rules{use super::types::{PlantKind,Stock,APPLE,IRON,LEMON,PLUM,WOOD};pub const TOTAL_TURNS:i32=300;pub const MAX_SIZE:i32=4;pub const MAX_FRUITS:i32=3;pub const WOOD_POINTS:i32=4;pub fn plant_cooldown(kind:PlantKind)->i32{match kind{PlantKind::Plum=>8,PlantKind::Lemon=>8,PlantKind::Apple=>9,PlantKind::Banana=>6,}}pub fn water_boost(kind:PlantKind)->i32{match kind{PlantKind::Plum=>5,PlantKind::Lemon=>5,PlantKind::Apple=>7,PlantKind::Banana=>2,}}pub fn tree_health_params(kind:PlantKind)->(i32,i32){match kind{PlantKind::Plum|PlantKind::Lemon=>(4,2),PlantKind::Apple=>(8,3),PlantKind::Banana=>(2,1),}}pub fn tree_health(kind:PlantKind,size:i32)->i32{let(base,slope)=tree_health_params(kind);base+slope*size}pub fn effective_cooldown(kind:PlantKind,near_water:bool)->i32{plant_cooldown(kind)-if near_water{water_boost(kind)}else{0}}pub fn training_cost(n:i32,talents:(i32,i32,i32,i32))->Stock{let(ms,cc,hp,chop)=talents;let mut cost=[0;6];cost[PLUM]=n+ms*ms;cost[LEMON]=n+cc*cc;cost[APPLE]=n+hp*hp;cost[IRON]=n+chop*chop;cost}pub fn score(inventory:&Stock)->i32{inventory[PLUM]+inventory[LEMON]+inventory[APPLE]+inventory[3]+WOOD_POINTS*inventory[WOOD]}pub fn item_index(name:&str)->Option<usize>{match name.to_ascii_uppercase().as_str(){"PLUM"=>Some(PLUM),"LEMON"=>Some(LEMON),"APPLE"=>Some(APPLE),"BANANA"=>Some(3),"IRON"=>Some(IRON),"WOOD"=>Some(WOOD),_=>None,}}}pub mod nav{use super::types::Cell;use std::collections::{BTreeMap,BTreeSet,VecDeque};pub const NEIGHBORS:[Cell;4]=[(0,1),(1,0),(0,-1),(-1,0)];pub fn manhattan(a:Cell,b:Cell)->i32{(a.0-b.0).abs()+(a.1-b.1).abs()}pub fn ortho_neighbors(cell:Cell)->[Cell;4]{[(cell.0,cell.1+1),(cell.0+1,cell.1),(cell.0,cell.1-1),(cell.0-1,cell.1),]}pub fn is_adjacent(a:Cell,b:Cell)->bool{manhattan(a,b)==1}pub fn bfs_distances(walkable:&BTreeSet<Cell>,sources:&[Cell])->BTreeMap<Cell,i32>{let mut dist=BTreeMap::new();let mut queue=VecDeque::new();for&cell in sources{if dist.insert(cell,0).is_none(){queue.push_back(cell);}}while let Some(cell)=queue.pop_front(){let d=dist[&cell];for delta in NEIGHBORS{let next=(cell.0+delta.0,cell.1+delta.1);if walkable.contains(&next)&&!dist.contains_key(&next){dist.insert(next,d+1);queue.push_back(next);}}}dist}pub fn next_cell(walkable:&BTreeSet<Cell>,current:Cell,target:Cell,speed:i32,)->Cell{let from_current=bfs_distances(walkable,&[current]);if let Some(distance)=from_current.get(&target){if*distance<=speed{return target;}}let to_target=if!from_current.contains_key(&target){if from_current.is_empty(){return current;}let best_manhattan=from_current.keys().map(|cell|manhattan(target,*cell)).min().unwrap();let goals:Vec<Cell> =from_current.keys().filter(|cell|manhattan(target,**cell)==best_manhattan).copied().collect();bfs_distances(walkable,&goals)}else{bfs_distances(walkable,&[target])};from_current.iter().filter(|(cell,distance)|**distance<=speed&&to_target.contains_key(*cell)).map(|(cell,_)|*cell).min_by_key(|cell|(to_target[cell],*cell)).unwrap_or(current)}}pub mod protocol{use super::rules::score;use super::types::{Cell,GameState,Plant,PlantKind,Stats,Unit};use std::collections::BTreeSet;use std::io::BufRead;#[derive(Clone,Debug)]pub struct StaticMap{pub width:i32,pub height:i32,pub walkable:BTreeSet<Cell>,pub shacks:[Cell;2],pub iron:BTreeSet<Cell>,pub water:BTreeSet<Cell>,}pub fn grid_rows(game:&GameState,seat:usize)->Vec<String>{(0..game.height).map(|y|{(0..game.width).map(|x|{let cell=(x,y);if cell==game.shacks[seat]{'0'}else if cell==game.shacks[1-seat]{'1'}else if game.iron.contains(&cell){'+'}else if game.water.contains(&cell){'~'}else if game.walkable.contains(&cell){'.'}else{'#'}}).collect()}).collect()}pub fn turn_block(game:&GameState,seat:usize)->String{let mut out=String::new();for player in[seat,1-seat]{let inv=game.inventories[player];out.push_str(&format!("{} {} {} {} {} {}\n",inv[0],inv[1],inv[2],inv[3],inv[4],inv[5]));}out.push_str(&format!("{}\n",game.plants.len()));for plant in&game.plants{out.push_str(&format!("{} {} {} {} {} {} {}\n",plant.kind.as_str(),plant.cell.0,plant.cell.1,plant.size,plant.health,plant.fruits,plant.cooldown));}out.push_str(&format!("{}\n",game.units.len()));for unit in&game.units{let rel_player=if unit.player==seat{0}else{1};out.push_str(&format!("{} {} {} {} {} {} {} {} {} {} {} {} {} {}\n",unit.id,rel_player,unit.cell.0,unit.cell.1,unit.stats.movement_speed,unit.stats.carry_capacity,unit.stats.harvest_power,unit.stats.chop_power,unit.carry[0],unit.carry[1],unit.carry[2],unit.carry[3],unit.carry[4],unit.carry[5]));}out}pub fn read_line(reader:&mut impl BufRead)->Option<String>{let mut line=String::new();match reader.read_line(&mut line){Ok(0)=>None,Ok(_)=>Some(line.trim_end_matches('\n').trim_end_matches('\r').to_string(),),Err(_)=>None,}}pub fn read_static_map(reader:&mut impl BufRead)->Option<StaticMap>{let header=read_line(reader)?;let mut parts=header.split_whitespace();let width=parts.next()?.parse().ok()?;let height=parts.next()?.parse().ok()?;let mut rows=Vec::new();for _ in 0..height{rows.push(read_line(reader)?);}Some(parse_static_map(width,height,&rows))}pub fn parse_static_map(width:i32,height:i32,rows:&[String])->StaticMap{let mut walkable=BTreeSet::new();let mut shacks=[(0,0),(0,0)];let mut iron=BTreeSet::new();let mut water=BTreeSet::new();for(y,row)in rows.iter().enumerate(){for(x,ch)in row.chars().enumerate(){let cell=(x as i32,y as i32);match ch{'0'=>shacks[0]=cell,'1'=>shacks[1]=cell,'.'=>{walkable.insert(cell);}'+'=>{iron.insert(cell);}'~'=>{water.insert(cell);}_=>{}}}}StaticMap{width,height,walkable,shacks,iron,water,}}pub fn read_turn(reader:&mut impl BufRead,map:&StaticMap,turn:i32,)->Option<GameState>{let mut inventories=[[0;6];2];for inv in&mut inventories{let line=read_line(reader)?;let values:Vec<i32> =line.split_whitespace().map(|value|value.parse().ok()).collect::<Option<Vec<i32>>>()?;if values.len()!=6{return None;}inv.copy_from_slice(&values);}let tree_count:usize=read_line(reader)?.trim().parse().ok()?;let mut plants=Vec::with_capacity(tree_count);for _ in 0..tree_count{let line=read_line(reader)?;let fields:Vec<&str> =line.split_whitespace().collect();if fields.len()!=7{return None;}plants.push(Plant{kind:PlantKind::parse(fields[0])?,cell:(fields[1].parse().ok()?,fields[2].parse().ok()?),size:fields[3].parse().ok()?,health:fields[4].parse().ok()?,fruits:fields[5].parse().ok()?,cooldown:fields[6].parse().ok()?,});}let unit_count:usize=read_line(reader)?.trim().parse().ok()?;let mut units=Vec::with_capacity(unit_count);let mut next_id=0;for _ in 0..unit_count{let line=read_line(reader)?;let values:Vec<i32> =line.split_whitespace().map(|value|value.parse().ok()).collect::<Option<Vec<i32>>>()?;if values.len()!=14{return None;}next_id=next_id.max(values[0]+1);units.push(Unit{id:values[0],player:values[1]as usize,cell:(values[2],values[3]),stats:Stats{movement_speed:values[4],carry_capacity:values[5],harvest_power:values[6],chop_power:values[7],},carry:[values[8],values[9],values[10],values[11],values[12],values[13],],});}Some(GameState{width:map.width,height:map.height,walkable:map.walkable.clone(),shacks:map.shacks,inventories,units,plants,scores:[score(&inventories[0]),score(&inventories[1])],turn,next_id,iron:map.iron.clone(),water:map.water.clone(),})}}pub use types::{Cell,GameState,Plant,PlantKind,Stats,Unit};}mod norxondor_three_worker_live_bot{use crate::game::rules::{training_cost,TOTAL_TURNS};use crate::game::types::{Cell,GameState,PlantKind,Unit,APPLE,IRON,LEMON,PLUM};use std::collections::{BTreeMap,BTreeSet,VecDeque};type Spec=(i32,i32,i32,i32);const MIN_TURNS_LEFT:i32=20;const MAX_TROLLS:usize=4;const MAX_ORCHARD:usize=2;const CHOPPER_SPEC:Spec=(1,2,1,2);const N_CHOPPERS:i32=2;const HARVESTERS:[Spec;3]=[(2,2,2,0),(1,2,2,0),(1,1,1,0)];const BASES:[Spec;4]=[(2,2,1,1),(2,3,1,2),(2,3,0,3),(2,4,0,3)];const CAPS:[Spec;4]=[(3,3,2,2),(4,5,2,2),(3,3,1,3),(3,4,1,3)];fn envi(name:&str,default:i32)->i32{std::env::var(name).ok().and_then(|value|value.parse().ok()).unwrap_or(default)}fn env_spec(name:&str,default:Spec)->Spec{if let Ok(value)=std::env::var(name){let parts:Vec<i32> =value.split(',').filter_map(|part|part.trim().parse().ok()).collect();if parts.len()==4{return(parts[0],parts[1],parts[2],parts[3]);}}default}fn manhattan(left:Cell,right:Cell)->i32{(left.0-right.0).abs()+(left.1-right.1).abs()}fn ortho(cell:Cell)->[Cell;4]{[(cell.0,cell.1+1),(cell.0+1,cell.1),(cell.0,cell.1-1),(cell.0-1,cell.1),]}fn bfs(game:&GameState,source:Cell)->BTreeMap<Cell,i32>{let mut distance=BTreeMap::from([(source,0)]);let mut queue=VecDeque::from([source]);while let Some((x,y))=queue.pop_front(){let next_distance=distance[&(x,y)]+1;for(dx,dy)in[(0,1),(1,0),(0,-1),(-1,0)]{let cell=(x+dx,y+dy);if game.walkable.contains(&cell)&&!distance.contains_key(&cell){distance.insert(cell,next_distance);queue.push_back(cell);}}}distance}fn affordable(inventory:&[i32;6],cost:&[i32;6],have_iron:bool)->bool{inventory[PLUM]>=cost[PLUM]&&inventory[LEMON]>=cost[LEMON]&&inventory[APPLE]>=cost[APPLE]&&(!have_iron||inventory[IRON]>=cost[IRON])}fn affordable_fruit(inventory:&[i32;6],cost:&[i32;6])->bool{inventory[PLUM]>=cost[PLUM]&&inventory[LEMON]>=cost[LEMON]&&inventory[APPLE]>=cost[APPLE]}fn stage_base(workers:i32)->Option<Spec>{if(1..=4).contains(&workers){Some(BASES[(workers-1)as usize])}else{None}}fn integer_sqrt(value:i32)->i32{let mut root=0;while(root+1)*(root+1)<=value.max(0){root+=1;}root}fn proposed_spec(workers:i32,inventory:&[i32;6],have_iron:bool)->Option<Spec>{if!(1..=4).contains(&workers){return None;}let index=(workers-1)as usize;let base=BASES[index];if!affordable(inventory,&training_cost(workers,base),have_iron){return None;}let cap=CAPS[index];Some((integer_sqrt(inventory[PLUM]-workers).min(cap.0),integer_sqrt(inventory[LEMON]-workers).min(cap.1),integer_sqrt(inventory[APPLE]-workers).min(cap.2),if have_iron{integer_sqrt(inventory[IRON]-workers).min(cap.3)}else{cap.3},))}struct SilverContinuation{memory:BTreeMap<i32,Cell>,}impl SilverContinuation{fn new()->Self{Self{memory:BTreeMap::new(),}}fn decide(&mut self,game:&GameState,player:usize)->Vec<String>{if game.turn==1{self.memory.clear();}let shack=game.shacks[player];let inventory=&game.inventories[player];let have_iron=!game.iron.is_empty();let mut units:Vec<&Unit> =game.units.iter().filter(|unit|unit.player==player).collect();units.sort_by_key(|unit|unit.id);let workers=units.len()as i32;let chopper_spec=env_spec("BOSS_CHOP",CHOPPER_SPEC);let want_chopper=(units.iter().filter(|unit|unit.stats.chop_power>=2).count()as i32)<envi("BOSS_NCHOP",N_CHOPPERS);let train_now=if want_chopper&&affordable(inventory,&training_cost(workers,chopper_spec),have_iron,){Some(chopper_spec)}else{HARVESTERS.iter().copied().find(|spec|{affordable(inventory,&training_cost(workers,*spec),have_iron)})};let need_iron=have_iron&&want_chopper&&inventory[IRON]<training_cost(workers,chopper_spec)[IRON]&&affordable_fruit(inventory,&training_cost(workers,chopper_spec));let has_real_chopper=units.iter().any(|unit|unit.stats.chop_power>=2);let bootstrap_id=if has_real_chopper{None}else{units.iter().filter(|unit|unit.stats.chop_power>=1).max_by_key(|unit|(unit.stats.carry_capacity,-unit.id)).map(|unit|unit.id)};let is_chopper=|unit:&Unit|{unit.stats.chop_power>=2||Some(unit.id)==bootstrap_id};let orchard=game.plants.iter().filter(|plant|{plant.kind==PlantKind::Plum&&manhattan(plant.cell,shack)<=3}).count();let need_index=(0..3usize).min_by_key(|index|inventory[*index]).unwrap();let need_kind=[PlantKind::Plum,PlantKind::Lemon,PlantKind::Apple][need_index];let mut reserved=BTreeSet::new();let mut command_by_id=BTreeMap::new();let mut actions=Vec::new();if game.turn==1{actions.push("MSG Eat your vegetables!".to_string());}for unit in&units{let chopper=is_chopper(unit);let distance=bfs(game,unit.cell);if unit.free_capacity()==0{self.memory.remove(&unit.id);if manhattan(unit.cell,shack)==1{let on_tree=game.plants.iter().any(|plant|plant.cell==unit.cell);if!chopper&&!on_tree&&orchard<MAX_ORCHARD&&unit.carry[PLUM]>0&&game.walkable.contains(&unit.cell){command_by_id.insert(unit.id,format!("PLANT {} PLUM",unit.id));}else{command_by_id.insert(unit.id,format!("DROP {}",unit.id));}}else{command_by_id.insert(unit.id,format!("MOVE {} {} {}",unit.id,shack.0,shack.1),);}continue;}if let Some(plant)=game.plants.iter().find(|plant|plant.cell==unit.cell){if chopper&&unit.stats.chop_power>0{command_by_id.insert(unit.id,format!("CHOP {}",unit.id));reserved.insert(unit.cell);continue;}if plant.fruits>0&&unit.stats.harvest_power>0&&unit.free_capacity()>0{command_by_id.insert(unit.id,format!("HARVEST {}",unit.id));reserved.insert(unit.cell);continue;}}if need_iron&&chopper&&unit.stats.chop_power>0&&game.iron.iter().any(|cell|manhattan(unit.cell,*cell)==1){command_by_id.insert(unit.id,format!("MINE {}",unit.id));continue;}let target=if chopper{let iron_cell=if need_iron{game.iron.iter().flat_map(|cell|ortho(*cell)).filter(|cell|{distance.contains_key(cell)&&!reserved.contains(cell)}).min_by_key(|cell|(distance[cell],*cell))}else{None};iron_cell.or_else(||{let opponent_shack=game.shacks[1-player];game.plants.iter().filter(|plant|{distance.contains_key(&plant.cell)&&!reserved.contains(&plant.cell)}).min_by_key(|plant|{(distance[&plant.cell]+manhattan(plant.cell,opponent_shack)-3*plant.size,-plant.size,plant.cell,)}).map(|plant|plant.cell)})}else{let sticky=self.memory.get(&unit.id).copied().filter(|cell|{game.plants.iter().any(|plant|plant.cell==*cell&&plant.fruits>0)&&!reserved.contains(cell)});let nearest_ripe=|kind:Option<PlantKind>|{game.plants.iter().filter(|plant|{plant.fruits>0&&!reserved.contains(&plant.cell)&&distance.contains_key(&plant.cell)}).filter(|plant|kind.map_or(true,|value|plant.kind==value)).min_by_key(|plant|(distance[&plant.cell],plant.cell)).map(|plant|plant.cell)};sticky.or_else(||nearest_ripe(Some(need_kind))).or_else(||nearest_ripe(None))};match target{Some(cell)=>{reserved.insert(cell);if!chopper{self.memory.insert(unit.id,cell);}command_by_id.insert(unit.id,format!("MOVE {} {} {}",unit.id,cell.0,cell.1),);}None=>{command_by_id.insert(unit.id,format!("MOVE {} {} {}",unit.id,shack.0,shack.1),);}}}actions.extend(command_by_id.into_values());if let Some(spec)=train_now{if units.len()<envi("BOSS_MAX",MAX_TROLLS as i32)as usize&&TOTAL_TURNS-game.turn>MIN_TURNS_LEFT&&!units.iter().any(|unit|unit.cell==shack){actions.push(format!("TRAIN {} {} {} {}",spec.0,spec.1,spec.2,spec.3));}}if actions.is_empty(){actions.push("WAIT".to_string());}actions}}fn bank_command(unit:&Unit,shack:Cell)->String{if manhattan(unit.cell,shack)==1{format!("DROP {}",unit.id)}else{format!("MOVE {} {} {}",unit.id,shack.0,shack.1)}}fn replace_unit_command(commands:&mut Vec<String>,unit_id:i32,replacement:String){commands.retain(|command|{let fields:Vec<_> =command.split_whitespace().collect();if fields.first().is_some_and(|verb|*verb=="TRAIN"){return false;}fields.get(1).and_then(|value|value.parse::<i32>().ok())!=Some(unit_id)});commands.push(replacement);}fn ranked_funding_command(game:&GameState,player:usize,unit:&Unit,workers:i32,rank:usize,reserved:&mut BTreeSet<Cell>,)->Option<String>{let cost=training_cost(workers,stage_base(workers)?);let inventory=&game.inventories[player];let mut needs:Vec<_> =(PLUM..=APPLE).map(|index|(cost[index]-inventory[index],index)).filter(|(deficit,_)|*deficit>0).collect();if!game.iron.is_empty()&&inventory[IRON]<cost[IRON]{needs.push((cost[IRON]-inventory[IRON],IRON));}needs.sort_by_key(|(deficit,index)|(-*deficit,*index));let(_,resource)=*needs.get(rank.min(needs.len().saturating_sub(1)))?;if unit.total_carried()>0&&(unit.free_capacity()==0||unit.carry[resource]>0){return Some(bank_command(unit,game.shacks[player]));}let distance=bfs(game,unit.cell);if resource<=APPLE{let kind=[PlantKind::Plum,PlantKind::Lemon,PlantKind::Apple][resource];if let Some(cell)=game.plants.iter().filter(|plant|plant.kind==kind&&distance.contains_key(&plant.cell)).filter(|plant|plant.cell==unit.cell||!reserved.contains(&plant.cell)).min_by_key(|plant|{(i32::from(plant.fruits<=0),distance[&plant.cell],plant.cooldown,plant.cell,)}).map(|plant|plant.cell){reserved.insert(cell);return Some(if cell==unit.cell{format!("HARVEST {}",unit.id)}else{format!("MOVE {} {} {}",unit.id,cell.0,cell.1)});}}else if resource==IRON&&unit.stats.chop_power>0{if game.iron.iter().any(|cell|manhattan(unit.cell,*cell)==1){reserved.insert(unit.cell);return Some(format!("MINE {}",unit.id));}if let Some(cell)=game.iron.iter().flat_map(|iron|ortho(*iron)).filter(|cell|distance.contains_key(cell)&&!reserved.contains(cell)).min_by_key(|cell|(distance[cell],*cell)){reserved.insert(cell);return Some(format!("MOVE {} {} {}",unit.id,cell.0,cell.1));}}(unit.total_carried()>0).then(||bank_command(unit,game.shacks[player]))}fn coordinated_three_worker_commands(mut commands:Vec<String>,game:&GameState,player:usize,)->Vec<String>{commands.retain(|command|!command.starts_with("TRAIN "));let mut units:Vec<&Unit> =game.units.iter().filter(|unit|unit.player==player).collect();units.sort_by_key(|unit|unit.id);let workers=units.len()as i32;if workers>=3{return commands;}let proposed=proposed_spec(workers,&game.inventories[player],!game.iron.is_empty());if proposed.is_none(){let funder_count=if workers==2{2}else{1};let mut reserved=BTreeSet::new();for(rank,unit)in units.iter().copied().filter(|unit|unit.stats.harvest_power>0).take(funder_count).enumerate(){if let Some(command)=ranked_funding_command(game,player,unit,workers,rank,&mut reserved){replace_unit_command(&mut commands,unit.id,command);}}}else if let Some(unit)=units.iter().copied().find(|unit|unit.cell==game.shacks[player]){if let Some(cell)=ortho(unit.cell).into_iter().find(|cell|game.walkable.contains(cell)){replace_unit_command(&mut commands,unit.id,format!("MOVE {} {} {}",unit.id,cell.0,cell.1),);}}if let Some(spec)=proposed{commands.push(format!("TRAIN {} {} {} {}",spec.0,spec.1,spec.2,spec.3));}commands}pub struct NorxondorThreeWorkerBot{continuation:SilverContinuation,}impl NorxondorThreeWorkerBot{pub fn new()->Self{Self{continuation:SilverContinuation::new(),}}pub fn commands(&mut self,game:&GameState)->Vec<String>{let commands=self.continuation.decide(game,0);coordinated_three_worker_commands(commands,game,0)}}}use crate::game::protocol::{read_static_map,read_turn};use crate::norxondor_three_worker_live_bot::NorxondorThreeWorkerBot;use std::io::{self,Write};fn main(){let stdin=io::stdin();let stdout=io::stdout();let mut reader=io::BufReader::new(stdin.lock());let mut out=io::BufWriter::new(stdout.lock());let Some(map)=read_static_map(&mut reader)else{return;};let mut bot=NorxondorThreeWorkerBot::new();let mut turn=1;while let Some(view)=read_turn(&mut reader,&map,turn){let commands=bot.commands(&view);writeln!(out,"{}",commands.join(";")).expect("write command line");out.flush().expect("flush command line");turn+=1;}}